 1	<?php
 2	/**
 3	 * Seeds system users into the test database.
 4	 * Invoked via: composer seed-tests
 5	 *
 6	 * @package Application
 7	 * @subpackage Tests
 8	 */
 9	
10	declare(strict_types=1);
11	
12	use Application\Bootstrap\Screen\TestSuiteBootstrap;
13	
14	$testsRoot = __DIR__;
15	
16	define('TESTS_ROOT', $testsRoot);
17	define('APP_TESTS_RUNNING', true);
18	
19	require_once __DIR__ . '/bootstrap.php';
20	
21	try
22	{
23	    TestSuiteBootstrap::seedSystemUsers();
24	}
25	catch(\Throwable $e)
26	{
27	    echo 'Seeding failed: ' . $e->getMessage() . PHP_EOL;
28	    exit(1);
29	}
30	
31	echo "Test database seeded successfully.\n";

